# Terraform Module: S3 Bucket + RDS + IAM

## Directory Layout

```
.
├── modules/
│   ├── s3-bucket/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam-service-account/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
└── versions.tf
```

## versions.tf

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Remote state, keyed per workspace -> environment isolation (AC 7)
  backend "s3" {
    bucket         = "myorg-tfstate"
    key            = "app/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "tf-locks"
  }
}
```

## variables.tf (root)

```hcl
variable "environment" {
  type        = string
  description = "Environment name (dev|prod)"
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  type        = string
  default     = "webapp"
}

variable "bucket_replication_region" {
  type        = string
  description = "Replica region for the assets bucket (null disables replication)"
  type        = string
  default     = null
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type    = bool
  default = false
}

variable "db_name" {
  type    = string
  default = "appdb"
}

variable "db_username" {
  type        = string
  description = "Master username. Password is generated and stored encrypted in Secrets Manager."
  default     = "appadmin"
}

variable "cluster_node_count" {
  type = number
}

variable "cluster_instance_type" {
  type = string
}
```

## main.tf (root)

```hcl
provider "aws" {
  region = var.aws_region

  assume_role {
    role_arn = "arn:aws:iam::${lookup(var.account_ids, var.environment)}:role/terraform-deployer"
  }

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"
}

# ---- Random DB password; never in Git (AC 3) ----
resource "random_password" "db" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}-db"
  kms_key_id  = aws_kms_key.db.arn
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = var.db_username
    password = random_password.db.result
    host     = module.rds.db_instance_address
    port     = module.rds.db_instance_port
    dbname   = var.db_name
  })
}

resource "aws_kms_key" "db" {
  description             = "${local.name_prefix} DB secret key"
  deletion_window_in_days = 30
}

# ---- Networking (minimal VPC for RDS) ----
module "network" {
  source          = "./modules/network"
  name_prefix     = local.name_prefix
  aws_region      = var.aws_region
}

# ---- S3 bucket ----
module "assets_bucket" {
  source               = "./modules/s3-bucket"
  name_prefix          = local.name_prefix
  replication_region   = var.bucket_replication_region
  service_account_arn  = module.service_account.role_arn
}

# ---- RDS PostgreSQL ----
module "rds" {
  source                = "./modules/rds"
  name_prefix           = local.name_prefix
  instance_class        = var.db_instance_class
  multi_az              = var.db_multi_az
  database_name         = var.db_name
  master_username       = var.db_username
  master_password       = random_password.db.result
  subnet_ids            = module.network.private_subnet_ids
  vpc_security_group_ids = [module.network.rds_sg_id]
}

# ---- IAM service account ----
module "service_account" {
  source         = "./modules/iam-service-account"
  name           = "${local.name_prefix}-svc"
  assets_bucket  = module.assets_bucket.bucket_name
  is_prod        = var.environment == "prod"
  oidc_provider_arn = var.environment == "prod" ? var.cluster_oidc_provider_arn : null
  oidc_subject   = var.environment == "prod" ? "system:serviceaccount:default:${var.project_name}" : null
}
```

*(For brevity `modules/network` is a thin wrapper around `terraform-aws-modules/vpc`; see end note.)*

---

## Module: `modules/s3-bucket/main.tf`

```hcl
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  principal  = var.service_account_arn
}

# KMS key for encryption
resource "aws_kms_key" "bucket" {
  description             = "${var.name_prefix}-assets"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "bucket" {
  name          = "alias/${var.name_prefix}-assets"
  target_key_id = aws_kms_key.bucket.key_id
}

resource "aws_s3_bucket" "this" {
  bucket        = "${var.name_prefix}-assets-${local.account_id}"
  force_destroy = var.replication_region == null # dev cleanup allowed, prod not
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }  # AC 1
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.bucket.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule { object_ownership = "BucketOwnerEnforced" }
}

# Replication (prod only): us-east-1 -> us-west-2
resource "aws_s3_bucket" "replica" {
  count  = var.replication_region == null ? 0 : 1
  provider = aws.replica
  bucket        = "${var.name_prefix}-assets-replica-${local.account_id}"
}

resource "aws_s3_bucket_versioning" "replica" {
  count  = var.replication_region == null ? 0 : 1
  provider = aws.replica
  bucket = aws_s3_bucket.replica[0].id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count  = var.replication_region == null ? 0 : 1
  provider = aws.replica
  bucket                  = aws_s3_bucket.replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_iam_role" "replication" {
  count = var.replication_region == null ? 0 : 1
  name  = "${var.name_prefix}-s3-replication"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "s3.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.replication_region == null ? 0 : 1
  name  = "replication"
  role  = aws_iam_role.replication[0].id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = ["s3:GetReplicationConfiguration", "s3:ListBucket"],
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Effect   = "Allow",
        Action   = ["s3:GetObjectVersion", "s3:GetObjectVersionAcl", "s3:GetObjectVersionTagging"]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Effect   = "Allow",
        Action   = ["s3:ReplicateObject", "s3:ReplicateDelete", "s3:ReplicateTags"]
        Resource = ["${aws_s3_bucket.replica[0].arn}/*"]
      },
      {
        Effect   = "Allow",
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.bucket.arn]
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.replication_region == null ? 0 : 1
  depends_on = [aws_s3_bucket_versioning.this]
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "all-objects"
    status = "Enabled"

    filter {}

    delete_marker_replication { status = "Disabled" }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD_IA"
      encryption_configuration {
        replica_kms_key_id = "" # uses SSE-S3 on replica to avoid cross-account CMK sharing
      }
    }
  }
}
```

`providers.tf` (bucket module):

```hcl
provider "aws" {
  alias  = "replica"
  region = coalesce(var.replication_region, "us-west-2")
}
```

### `modules/s3-bucket/variables.tf`

```hcl
variable "name_prefix" { type = string }
variable "replication_region" {
  type    = string
  default = null
}
variable "service_account_arn" { type = string }
```

### `modules/s3-bucket/outputs.tf`

```hcl
output "bucket_name" { value = aws_s3_bucket.this.bucket }
output "bucket_arn" { value = aws_s3_bucket.this.arn }
output "replica_bucket_name" {
  value = try(aws_s3_bucket.replica[0].bucket, null)
}
```

Grant the app read access inside the bucket:

```hcl
# appended in module main.tf: least-privilege read policy for the service account (AC 4)
resource "aws_s3_bucket_policy" "read_only" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Sid       = "ServiceAccountReadOnly",
      Effect    = "Allow",
      Principal = { AWS = local.principal },
      Action    = ["s3:GetObject", "s3:ListBucket"],
      Resource  = [aws_s3_bucket.this.arn, "${aws_s3_bucket.this.arn}/*"]
    }]
  })
}
```

