## Module: `modules/rds/main.tf`

```hcl
resource "aws_db_parameter_group" "this" {
  name   = "${var.name_prefix}-pg15"
  family = "postgres15"

  parameter {
    name  = "log_min_duration_statement"
    value = "2000"
  }
}

resource "aws_db_instance" "this" {
  identifier     = "${var.name_prefix}-pg"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.instance_class

  allocated_storage     = 20
  max_allocated_storage = var.multi_az ? 500 : 100
  storage_encrypted     = true   # required for prod, harmless elsewhere

  db_name  = var.database_name
  username = var.master_username
  password = var.master_password

  port = 5432

  multi_az               = var.multi_az                       # AC (prod spec)
  publicly_accessible    = false                              # AC 2
  deletion_protection    = true                               # AC 2 — both envs per acceptance criteria
  backup_retention_period = 14                                # AC 2 (>= 7)
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:30-sun:05:30"

  db_subnet_group_name   = aws_db_subnet_group.this.name
  vpc_security_group_ids = var.vpc_security_group_ids
  parameter_group_name   = aws_db_parameter_group.this.name

  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.name_prefix}-final-snapshot"
  copy_tags_to_snapshot     = true

  auto_minor_version_upgrade = true
}

resource "aws_db_subnet_group" "this" {
  name       = "${var.name_prefix}-dbsubnets"
  subnet_ids = var.subnet_ids
}
```

### Variables / Outputs

```hcl
# variables.tf
variable "name_prefix"             { type = string }
variable "instance_class"          { type = string }
variable "multi_az"                { type = bool }
variable "database_name"           { type = string }
variable "master_username"         { type = string }
variable "master_password"         { type = string, sensitive = true }
variable "subnet_ids"              { type = list(string) }
variable "vpc_security_group_ids"  { type = list(string) }

# outputs.tf
output "db_instance_address" { value = aws_db_instance.this.address }
output "db_instance_port"    { value = aws_db_instance.this.port }
output "db_endpoint_sg_id"   { value = aws_db_instance.this.vpc_security_groups[0] }
```

Note: because `deletion_protection` must be flipped off before destroy, document `terraform state` or a `deletion_protection_override` variable if environments are truly ephemeral in dev.

---

## Module: `modules/iam-service-account/main.tf`

```hcl
data "aws_partition" "current" {}

# Dev: programmatic-access user with scoped inline policies
resource "aws_iam_user" "this" {
  count = var.is_prod ? 0 : 1
  name  = var.name
}

resource "aws_iam_access_key" "this" {
  count = var.is_prod ? 0 : 1
  user  = aws_iam_user.this[0].name
}

resource "aws_iam_user_policy" "scoped" {
  count = var.is_prod ? 0 : 1
  name  = "bucket-read-write"
  user  = aws_iam_user.this[0].name
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"] # scoped, no wildcards
        Resource = [var.assets_bucket_arn, "${var.assets_bucket_arn}/*"]
      }
    ]
  })
}

# Prod: least-privilege role trusted by the cluster's OIDC provider — no static keys
resource "aws_iam_role" "oidc" {
  count = var.is_prod ? 1 : 0
  name  = "${var.name}-oidc"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = {
        Federated = var.oidc_provider_arn
      },
      Action = "sts:AssumeRoleWithWebIdentity",
      Condition = {
        StringEquals = {
          "${replace(var.oidc_provider_url, "https://", "")}:sub" = var.oidc_subject
        }
      }
    }]
  })
}

resource "aws_iam_role_policy" "scoped" {
  count = var.is_prod ? 1 : 0
  name  = "bucket-scoped"
  role  = aws_iam_role.oidc[0].id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = "${var.assets_bucket_arn}/prod/*"
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = var.assets_bucket_arn
        Condition = {
          StringLike = { "s3:prefix" = ["prod/*"] }
        }
      }
    ]
  })
}
```

### Variables / Outputs

```hcl
variable "name"              { type = string }
variable "assets_bucket_arn" { type = string }
variable "is_prod"           { type = bool }
variable "oidc_provider_arn" { type = string, default = null }
variable "oidc_subject"      { type = string, default = null }

output "user_name"   { value = try(aws_iam_user.this[0].name, null) }
output "access_key_id" {
  value     = try(aws_iam_access_key.this[0].id, null)
}
# Secret access key is intentionally NOT output as plaintext into state consumers;
# retrieve via Secrets Manager where it's mirrored at creation time.
output "role_arn" { value = try(aws_iam_role.oidc[0].arn, try(aws_iam_user.this[0].arn, null)) }
```

